function readDrafts(){try{const raw=localStorage.getItem(draftKey);if(!raw)return;const v=window.FLIGHTDESK_BACKUP?.parse?window.FLIGHTDESK_BACKUP.parse(raw):JSON.parse(raw);if(v.version!==1||!v.drafts||Array.isArray(v.drafts)||typeof v.drafts!=='object')throw Error('Unrecognised debrief drafts');for(const [id,d]of Object.entries(v.drafts)){if(!id||!d||!Number.isFinite(Date.parse(d.savedAt))||!d.data||typeof d.data!=='object'||Object.values(d.data).some(x=>!['string','boolean'].includes(typeof x)))throw Error('Invalid debrief recovery draft');}debriefDrafts=v;}catch(error){draftStorageBlocked=true;draftStatus.textContent='Existing debrief recovery drafts could not be read and were not overwritten. Keep a backup before repair. '+error.message;}}
function draftValues(){return Object.fromEntries(debriefFields.map(id=>[id,['debriefnothing','debriefdefect'].includes(id)?el(id).checked:el(id).value]));}
function savedValues(r){const d=r?.debriefs.at(-1);return{debriefoutcome:d?.outcome||(['CANCELLED','POSTPONED'].includes(r?.phase)?r.phase.toLowerCase():''),landingcharge:d?.landingCharge===null||d?.landingCharge===undefined?'':String(d.landingCharge),landingpacknotes:d?.packNotes||'',debriefnothing:!!d?.nothingToReport,debriefdefect:!!d?.defect,debriefnote:d?.note||'',debrieffollowup:d?.followup||'',debriefdeliverables:d?.deliverables||''};}
function dirtyDebrief(){const r=current();return !!r&&JSON.stringify(draftValues())!==JSON.stringify(savedValues(r));}
