function showDraftStatus(){if(draftStorageBlocked)return;const r=current(),d=r&&debriefDrafts.drafts[r.id];draftStatus.textContent=!r?'No flight selected.':dirtyDebrief()?'Post-flight changes not saved as a revision.'+(d?' Recovery draft saved in this browser '+local(d.savedAt)+'.':' Recovery draft not yet saved.'):'Saved post-flight revision '+(r.debriefs.at(-1)?local(r.debriefs.at(-1).recordedAt):'not yet recorded')+'.';}
function autosaveDebrief(){const r=current();if(!r)return;try{if(dirtyDebrief())debriefDrafts.drafts[r.id]={savedAt:now(),data:draftValues()};else delete debriefDrafts.drafts[r.id];writeDrafts();showDraftStatus();}catch(error){draftStatus.textContent='Post-flight recovery draft NOT saved: '+error.message;}}
function clearDraft(id,strict=false){const old=debriefDrafts.drafts[id];delete debriefDrafts.drafts[id];try{writeDrafts();}catch(error){if(old)debriefDrafts.drafts[id]=old;if(strict)throw Error('Recovery draft could not be discarded: '+error.message);draftStatus.textContent='Debrief revision saved, but recovery draft cleanup failed: '+error.message;}}
function flightReference(r){return r?window.FLIGHT_RECORDS?.reference?.(r.missionId||r.id)||(r.missionId||r.id):'';}
function applySelection(id){selected=id;fillDebrief();render();const r=current();window.dispatchEvent(new CustomEvent('flightdesk:sortieselected',{detail:{id:r?.id||null,missionId:r?.missionId||null,reference:flightReference(r)}}));return true;}
