function guardLeave(callback){if(pending){el('flightlogstatus').textContent='An unsaved flight-log update remains in memory. Download the recovery file and resolve it before switching flights.';return false;}if(dirtyDebrief()){pendingSelection={callback};switchPrompt.hidden=false;switchPrompt.scrollIntoView?.({block:'nearest'});return false;}callback?.();return true;}
function continueSelection(discard=false){const action=pendingSelection;if(!action)return;if(discard){clearDraft(selected,true);fillDebrief(false);}pendingSelection=null;switchPrompt.hidden=true;if(action.id)applySelection(action.id);else action.callback?.();}
