function download(name,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function commit(next){if(pending)throw Error('An earlier flight-log update remains unsaved. Download its recovery file before reloading and importing it; no new log action was saved.');if(blocked)throw Error('Existing flight data needs recovery before further recording');C.validate(next);try{localStorage.setItem(key,JSON.stringify(next));}catch(error){pending=next;el('recoverflightdownload').hidden=false;throw Error('Flight log NOT durably saved: '+error.message+'. Download the recovery file and retain it before continuing.');}const changedSortieId=next.sorties.filter(r=>JSON.stringify(r)!==JSON.stringify(state.sorties.find(old=>old.id===r.id))).at(-1)?.id||null;state=next;pending=null;el('recoverflightdownload').hidden=true;el('flightlogstatus').textContent='Flight events saved in this browser · '+new Date().toISOString();window.dispatchEvent(new CustomEvent('flightdesk:flightlog',{detail:{selectedSortieId:selected,changedSortieId,sortieIds:state.sorties.map(r=>r.id)}}));render();return true;}
