function start(unassessed){if(dirtyDebrief())throw Error('Save or discard current post-flight changes first.');if(pending)throw Error('Download the unsaved recovery log first.');if(C.active(state))throw Error('A flight is already active');const ctx=recordingContext(),time=now(),id=uid(),next=C.start(state,{id,now:time,takeoffAt:unassessed?instant(el('recoverytakeoff').value):time,briefing:ctx.brief,independent:true,unassessed,notes:unassessed?el('recoveryreason').value:'Independent factual recording. Linked briefing is not revalidated or a clearance.',version:version()});commit(next);selected=C.active(state).id;window.flightAirspaceBeginSortie?.();fillDebrief();render();}
el('recordtakeoff').onclick=()=>run(()=>start(false));el('recoverairborne').onclick=()=>run(()=>start(true));
function add(type,notes=''){const active=C.active(state),ctx=recordingContext();let r=active||ctx.existing,next=state;const time=now();if(!r){if(['landing','abort','outcome-unknown'].includes(type))throw Error('No flight is airborne');next=C.ground(state,{id:uid(),now:time,briefing:ctx.brief,version:version()});r=next.sorties.at(-1);}if(!active)notes=(r.phase==='GROUND'?'Ground event · before take-off: ':'Ground event · after flight: ')+notes;commit(C.event(next,r.id,{eventId:uid(),type,now:time,notes,version:version()}));selected=r.id;if(type==='landing'||type==='outcome-unknown'){selectSortie(r.id);window.updateFlightdeskDecision?.();}render();}
el('recordlanding').onclick=()=>run(()=>add('landing'));el('recordabort').onclick=()=>run(()=>add('abort','Pilot recorded abort/return intention; aircraft landing not yet confirmed.'));el('unknownlanding').onclick=()=>run(()=>add('outcome-unknown',el('recoveryreason').value));el('recordevent').onclick=()=>run(()=>{add(el('flighteventtype').value,el('flighteventnote').value);el('flighteventnote').value='';});
