el('cancelplan').onclick=()=>run(()=>{if(C.active(state))throw Error('An airborne flight cannot be cancelled as though it never flew');if(dirtyDebrief())throw Error('Save or discard the current post-flight changes first.');const ctx=recordingContext();if(ctx.existing?.phase==='GROUND'){const time=now(),outcome=el('canceloutcome').value,next=C.event(state,ctx.existing.id,{eventId:uid(),type:outcome.toLowerCase(),now:time,notes:'No take-off recorded',version:version()}),r=next.sorties.find(r=>r.id===ctx.existing.id);r.phase=outcome;commit(next);selected=r.id;fillDebrief();render();return;}C.assertMissionAvailable(state,ctx.brief.missionId);const brief=window.flightMissionAPI?.saveBriefing();if(!brief)throw Error('Enter project and mission titles first');const time=now(),id=uid(),outcome=el('canceloutcome').value;const r={id,createdAt:time,phase:outcome,missionId:brief.missionId,projectTitle:brief.projectTitle,missionTitle:brief.missionTitle,briefingId:brief.id,briefing:brief,assessment:'NOT_FLOWN',takeoffAt:null,landingAt:null,events:[{id:uid(),type:outcome.toLowerCase(),recordedAt:time,occurredAt:time,appVersion:version()}],debriefs:[],appVersion:version()};commit({...state,sorties:[...state.sorties,r]});selected=id;fillDebrief();render();});
function fillDebrief(restore=true){const r=current(),d=r?.debriefs.at(-1);el('debriefoutcome').value=d?.outcome||(['CANCELLED','POSTPONED'].includes(r?.phase)?r.phase.toLowerCase():'');for(const[id,k]of [['landingcharge','landingCharge'],['landingpacknotes','packNotes'],['debriefnote','note'],['debrieffollowup','followup'],['debriefdeliverables','deliverables']])el(id).value=String(d?.[k]??'');el('debriefnothing').checked=!!d?.nothingToReport;el('debriefdefect').checked=!!d?.defect;const candidate=restore&&r&&debriefDrafts.drafts[r.id],draft=candidate&&Date.parse(candidate.savedAt)>(d?Date.parse(d.recordedAt):0)?candidate:null;if(draft)for(const id of debriefFields){const v=draft.data[id];if(v!==undefined){if(['debriefnothing','debriefdefect'].includes(id))el(id).checked=!!v;else el(id).value=v;}}showDraftStatus();}
