el('downloadsorties').onclick=()=>download('flightdesk-flight-debrief-records.html','<!doctype html><html lang="en"><meta charset="utf-8"><title>Flightdesk flight/debrief records</title><style>body{font:16px system-ui;max-width:1000px;margin:30px auto;padding:20px}pre{white-space:pre-wrap;overflow-wrap:anywhere}article{break-before:page}</style><h1>Flightdesk UK · flight and debrief records</h1><p>Pilot-entered records, not independent compliance verification or a tamper-proof logbook. Exported '+escape(now())+'; app '+escape(version())+'. Times stored in UTC; no aircraft telemetry.</p>'+state.sorties.map(r=>'<article><h2>'+escape(r.projectTitle)+' / '+escape(r.missionTitle)+'</h2><p>'+escape(r.phase)+' · '+escape(r.assessment)+' · actual elapsed '+escape(C.elapsed(r)===null?'not recorded':C.elapsed(r).toFixed(1)+' min')+'</p><pre>'+escape(JSON.stringify(r,null,2))+'</pre></article>').join(''),'text/html');
function timer(){const r=C.active(state),timeUncertain=!!r&&(Date.now()<Date.parse(r.takeoffAt)||C.elapsed(r)>180);banner.hidden=!r;banner.textContent=r?'AIRBORNE · '+r.assessment+' recorded at launch. The readiness cards below concern a future take-off; they do not rewrite this flight. Use Flight to record landing.':'';const shown=r||state.sorties.find(s=>s.missionId===(el('flightlogselect')?.value||window.flightMissionAPI?.current()?.missionId)),clock=C.clock(shown,Date.now());el('flightairbornestate').textContent=r?'Airborne':'Not airborne';el('flightelapsed').textContent=clock.text;el('flighttimefacts').textContent=shown?'Take-off: '+local(shown.takeoffAt)+' · Landing: '+local(shown.landingAt)+(r?' · Elapsed airborne time':' · Final recorded duration'):'Elapsed airborne time · timer starts after take-off is recorded.';const allowance=Number(r?.briefing?.values?.duration);el('flightremaining').textContent=r&&allowance>0?'Estimated allowance remaining: '+Math.max(0,allowance-C.elapsed(r)).toFixed(1)+' min · estimate only':'';el('flightlivestatus').textContent=r?'Airborne — '+(!navigator.onLine?'offline; live services unavailable. ':'')+'Reassess conditions / follow your operating and emergency plan.'+(timeUncertain?' Clock/time concern: elapsed time is outside the supported planning range; verify actual times and record a correction when appropriate.':''): 'No flight is recorded airborne. Pre-flight readiness is separate from recorded outcomes.';}
function render(){const r=current(),active=C.active(state);el('flightphase').textContent=active?'AIRBORNE · '+(active.briefing?.readiness?.recommendation||active.assessment):'No active flight';const ctx=recordingContext(),closed=ctx.existing&&ctx.existing.phase!=='GROUND';el('recordtakeoff').disabled=!!active||blocked||!!pending||!!closed;el('launchdisabledreason').textContent=active?'Record landing before another take-off.':blocked||pending?'Resolve flight log storage before continuing.':closed?'This reference already has a flight outcome. Create a new flight for another take-off.':'Recording is available independently of pre-flight readiness, including offline. Select a saved/imported briefing or use the current field setup. Recording facts does not approve a flight.';for(const id of ['recordlanding','recordabort']){el(id).disabled=!active||blocked||!!pending;el(id).title=active?'Record this action for the airborne flight':'No flight is recorded airborne.';}el('flightcontext').textContent=active?[flightReference(active),active.projectTitle,active.missionTitle,'Aircraft: '+(active.briefing?.values?.aircraft||'not recorded'),'Pilot: '+(active.briefing?.pilot?.name||'not recorded'),'Battery: '+(active.briefing?.battery?.name||'not recorded'),'Landing reserve: '+(active.briefing?.values?.reserve||'not recorded')+'%'].join(' · '):'';
const select=el('sortieselect');if(select.options.length!==state.sorties.length||Array.from(select.options).some((o,i)=>o.value!==state.sorties[i]?.id)){select.replaceChildren();for(const item of state.sorties){const option=document.createElement('option');option.value=item.id;option.textContent=flightReference(item)+' · '+item.projectTitle+' / '+item.missionTitle+' · '+item.phase+' · '+local(item.createdAt);select.append(option);}}for(const option of select.options){const item=state.sorties.find(s=>s.id===option.value);if(item)option.textContent=flightReference(item)+' · '+item.projectTitle+' / '+item.missionTitle+' · '+item.phase+' · '+local(item.createdAt);}for(const [id,complete]of [['flightcard',!!r&&!['GROUND','AIRBORNE'].includes(r.phase)],['postflightcard',r?.phase==='DEBRIEF_COMPLETE']]){const d=el(id).querySelector('.field-section');if(d){d.classList.toggle('section-complete',complete);d.classList.toggle('section-attention',!!r&&!complete);d.classList.toggle('section-warning',id==='flightcard'&&!!active);}}select.value=r?.id||'';el('sortiesummary').textContent=r?flightReference(r)+' · '+r.phase+' · '+r.assessment+' · Take-off '+local(r.takeoffAt)+' · Landing '+local(r.landingAt)+' · Actual duration '+(C.elapsed(r)===null?'not recorded':C.elapsed(r).toFixed(1)+' min')+(r.clockUncertain?' · Time uncertainty/correction recorded':''): 'No flight has been recorded. Saving a briefing alone does not record a flight.';el('savedebrief').disabled=!r||['GROUND','AIRBORNE'].includes(r.phase);el('debriefrevisionhistory').replaceChildren();for(const [index,d]of (r?.debriefs||[]).entries()){const li=document.createElement('li');li.textContent='Revision '+(index+1)+' · '+local(d.recordedAt)+' · '+(d.complete?'complete':'incomplete')+' · '+(d.outcome||'outcome not recorded')+' · landing charge '+(d.landingCharge===null||d.landingCharge===undefined?'not recorded':d.landingCharge+'%')+(d.nothingToReport?' · Nothing to report':'')+(d.defect?' · Defect reported':'')+(d.note?' · '+d.note:'')+(d.followup?' · Follow-up: '+d.followup:'')+(d.packNotes?' · Pack readings: '+d.packNotes:'')+(d.deliverables?' · Deliverables: '+d.deliverables:'');el('debriefrevisionhistory').append(li);}el('flightevents').replaceChildren();for(const event of (active||r)?.events||[]){const li=document.createElement('li');li.textContent=local(event.occurredAt)+' · '+event.type+(event.notes?' · '+event.notes:'');el('flightevents').append(li);}const flown=state.sorties.filter(s=>s.takeoffAt),known=flown.map(s=>C.elapsed(s)).filter(Number.isFinite);el('flighttotals').textContent=flown.length+' sortie(s) with recorded take-off · '+known.reduce((a,b)=>a+b,0).toFixed(1)+' min recorded elapsed · '+flown.filter(s=>!s.landingAt).length+' without recorded landing. No flight counts are converted into full battery cycles.';timer();}
const banner=document.createElement('p');banner.className='phase-banner';banner.hidden=true;el('decisioncard').before(banner);
const recoveryInput=document.createElement('input');recoveryInput.type='file';recoveryInput.accept='.json,application/json';recoveryInput.hidden=true;card.querySelector('.body').append(recoveryInput);const recoveryButton=document.createElement('button');recoveryButton.type='button';recoveryButton.className='btn';recoveryButton.id='flightrecoveryimport';recoveryButton.textContent='Import flight-log recovery file';el('recoverflightdownload').after(recoveryButton);recoveryButton.onclick=()=>recoveryInput.click();recoveryInput.onchange=async()=>{try{const file=recoveryInput.files?.[0];if(!file)return;if(file.size>50*1024*1024)throw Error('Recovery file exceeds 50 MB');const data=window.FLIGHTDESK_BACKUP.parse(await file.text());if(data.format!=='flightdesk-flight-log-recovery')throw Error('Use a Flightdesk flight-log recovery file; use Upload past flight records for all-data backups');commit(C.mergeRecovery(state,{version:data.version,sorties:data.sorties}));selected=C.active(state)?.id||state.sorties.at(-1)?.id||'';fillDebrief();render();}catch(error){el('flightlogstatus').textContent='Recovery file not imported: '+error.message;}finally{recoveryInput.value='';}};
window.flightLifecycleAPI={selectSortie,chooseSortie:selectSortie,guardLeave,pendingWork:()=>({sortieId:current()?.id||null,dirty:dirtyDebrief(),draftSavedAt:debriefDrafts.drafts[current()?.id]?.savedAt||null,pendingFlightLog:!!pending,pendingSelection:!!pendingSelection}),current:()=>current()?JSON.parse(JSON.stringify(current())):null,sorties:()=>JSON.parse(JSON.stringify(state.sorties)),draftSnapshot:()=>JSON.parse(JSON.stringify(debriefDrafts)),saveDebrief:()=>{try{return saveDebrief();}catch(error){el('debriefstatus').textContent=error.message;return false;}},discardDebrief:()=>{try{clearDraft(selected,true);fillDebrief(false);showDraftStatus();return true;}catch(error){el('debriefstatus').textContent=error.message;return false;}}};
window.flightActiveSortie=()=>C.active(state);window.flightHasActive=()=>!!C.active(state);window.addEventListener('flightdesk:restored',()=>{try{state=C.validate(JSON.parse(localStorage.getItem(key)||'{"version":1,"sorties":[]}'));selected=C.active(state)?.id||state.sorties.at(-1)?.id||'';blocked=false;debriefDrafts={version:1,drafts:{}};draftStorageBlocked=false;readDrafts();fillDebrief();render();}catch(error){blocked=true;el('flightlogstatus').textContent='Restored flight log requires recovery: '+error.message;}});window.flightLifecycleSnapshot=()=>JSON.parse(JSON.stringify(state));window.addEventListener('flightdesk:decision',e=>{lastDecision=e.detail;render();});window.addEventListener('flightdesk:recordtarget',render);window.addEventListener('online',timer);window.addEventListener('offline',timer);document.addEventListener('visibilitychange',timer);setInterval(timer,1000);fillDebrief();render();
